public sealed interface Shape permits Circle, Rectangle, Triangle {}

public record Circle(double radius) implements Shape {}
public record Rectangle(double length, double width) implements Shape {}
public record Triangle(double base, double height) implements Shape {}

public class GeometryEngine {
    public static double calculateArea(Shape shape) {
        return switch (shape) {
            case Circle(var r) -> Math.PI * r * r;
            case Rectangle(var l, var w) when l == w -> l * w; // Guard pattern
            case Rectangle(var l, var w) -> l * w;
            case Triangle(var b, var h) -> 0.5 * b * h;
            // No default needed because Shape is a sealed interface and all cases are covered
        };
    }

    public static void processLegacyCheck(Object obj) {
        if (obj instanceof String s && !s.isEmpty()) {
            System.out.println("Valid string of length: " + s.length());
        }
    }
}
